-- Q5.3 Part A.1
-- Count rows in both source tables.

SELECT COUNT(*) AS game_modes_count
FROM game_modes;

SELECT COUNT(*) AS matches_count
FROM matches;


-- Q5.3 Part A.2
-- Combine every game mode with every match.

SELECT
    gm.mode_name,
    m.match_label
FROM game_modes gm
CROSS JOIN matches m
ORDER BY gm.mode_id, m.match_id;


-- Q5.3 Part A.3
-- Count rows generated by the CROSS JOIN.

SELECT COUNT(*) AS cross_join_rows
FROM game_modes gm
CROSS JOIN matches m;



-- Q5.3 Part B.1
-- Examine how PostgreSQL executes the three-table join.

EXPLAIN
SELECT
    p.player_id,
    p.player_name AS actor,
    m.match_id,
    m.match_label AS producer,
    mp.participation_id AS event_id,
    mp.joined_at AS event_date_time
FROM players p
INNER JOIN match_participants mp
    ON p.player_id = mp.player_id
INNER JOIN matches m
    ON mp.match_id = m.match_id
ORDER BY mp.joined_at;




EXPLAIN ANALYZE
SELECT
    p.player_id,
    p.player_name AS actor,
    m.match_id,
    m.match_label AS producer,
    mp.participation_id AS event_id,
    mp.joined_at AS event_date_time
FROM players p
INNER JOIN match_participants mp
    ON p.player_id = mp.player_id
INNER JOIN matches m
    ON mp.match_id = m.match_id
ORDER BY mp.joined_at;
